INSERT INTO questionnaire (template_key, name, description, activity_type, renderer, sort_order, suppressed, psp_id)
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'a_respondent_name', 'Respondent Name', 'TEXT', NULL, 'Name of the person completing this questionnaire.', 'Section A  Entity & Plan Context', 1, 100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'a_respondent_email', 'Respondent Email', 'TEXT', NULL, 'Email address for follow-up questions about your responses.', 'Section A  Entity & Plan Context', 1, 200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'a_employer_legal_name', 'Employer Legal Name', 'TEXT', NULL, 'Enter the legal name of the entity that sponsors the cafeteria plan.', 'Section A  Entity & Plan Context', 1, 300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'a_plan_year_end_date', 'Plan Year End Date', 'DATE', NULL, 'Enter the last day of the plan year being tested.', 'Section A  Entity & Plan Context', 1, 400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'a_entity_type', 'Entity Type', 'SELECT', 'C-Corporation|S-Corporation|LLC / Partnership|Sole Proprietorship|Non-Profit (501(c)(3))|Government Entity', 'Select the legal entity type of the plan sponsor. If the employer is part of a controlled group with mixed entity types, select the entity type of the entity that sponsors the cafeteria plan.', 'Section A  Entity & Plan Context', 1, 500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'b_controlled_group', 'Is the employer part of a controlled group, parent-subsidiary group, or affiliated service group?', 'RADIO', 'Yes|No', 'Related entities include parent-subsidiary groups (80%+ ownership), brother-sister groups (common ownership by 5 or fewer individuals), and affiliated service groups (service organizations with shared ownership or service relationships).', 'Section B  Controlled Group / Affiliated Service Group', 1, 600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'b_non_covered_entities', 'Are there any related entities whose employees are NOT eligible to participate in this cafeteria plan?', 'RADIO', 'Yes|No', 'Employees of non-covered related entities must still be included in the nondiscrimination testing population even though they cannot participate in the plan.', 'Section B  Controlled Group / Affiliated Service Group', 1, 700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'b_non_covered_entity_names', 'List the names of all related entities whose employees are NOT eligible', 'TEXTAREA', NULL, 'Include every related entity in the group whose employees cannot enroll in the cafeteria plan.', 'Section B  Controlled Group / Affiliated Service Group', 1, 800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'b_non_covered_entity_employee_count', 'Total number of employees across these non-covered related entities', 'NUMBER', NULL, 'Count all common-law employees who were employed on any day during the plan year at the non-covered related entities listed above.', 'Section B  Controlled Group / Affiliated Service Group', 1, 900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'c_total_employees', 'Total number of common-law employees of the plan sponsor', 'NUMBER', NULL, 'Count all common-law employees who were employed on any day during the plan year. Do not include independent contractors, leased employees, or employees of related entities (those are captured separately).', 'Section C  Workforce Overview', 1, 1000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'c_cba_covered', 'Are any employees covered by a collective bargaining agreement (CBA)?', 'RADIO', 'Yes|No', 'Employees covered by a CBA may be excludable from testing if cafeteria plan benefits were the subject of good-faith bargaining.', 'Section C  Workforce Overview', 1, 1100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'c_cba_good_faith', 'Were cafeteria plan benefits the subject of good-faith bargaining?', 'RADIO', 'Yes|No', 'CBA employees can only be excluded from testing if cafeteria plan benefits were actually bargained for in the agreement. If unsure, check the collective bargaining agreement or contact your labor counsel.', 'Section C  Workforce Overview', 1, 1200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'c_cba_employee_count', 'Number of employees covered by the CBA', 'NUMBER', NULL, 'Count all common-law employees covered by the collective bargaining agreement(s).', 'Section C  Workforce Overview', 1, 1300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'c_cba_eligible', 'Are CBA-covered employees eligible to participate in the cafeteria plan?', 'RADIO', 'Yes|No', 'CBA employees may be excludable from the testing population, but if they are eligible and participating, their elections still count in certain test calculations.', 'Section C  Workforce Overview', 1, 1400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'd_benefits_offered', 'Which benefits are offered under the cafeteria plan?', 'CHECKBOX', 'Pre-tax insurance premiums (POP)|Health FSA|Limited Purpose FSA|Dependent Care FSA|HSA contributions|Other', 'Select all benefits available to employees through the cafeteria plan. Pre-tax insurance premiums (POP) means employees can pay their share of employer-sponsored health, dental, or vision premiums on a pre-tax basis.', 'Section D  Benefits Offered', 1, 1500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'd_benefits_other_describe', 'If Other, please describe', 'TEXT', NULL, 'Describe any additional benefits offered through the cafeteria plan not listed above.', 'Section D  Benefits Offered', 0, 1600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'f_simple_cafeteria', 'Has the employer adopted a Simple Cafeteria Plan under IRC §125(j)?', 'RADIO', 'Yes|No|Unsure', 'A Simple Cafeteria Plan is a special safe harbor for small employers. Your plan document or benefits advisor can confirm whether this has been adopted.', 'Section F  Simple Cafeteria Plan Safe Harbor', 1, 1700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'f_100_or_fewer', 'Did the employer average 100 or fewer employees during the two preceding plan years?', 'RADIO', 'Yes|No', 'Only employers averaging 100 or fewer employees during both of the two preceding plan years are eligible for the Simple Cafeteria Plan safe harbor.', 'Section F  Simple Cafeteria Plan Safe Harbor', 1, 1800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'f_contribution_requirement', 'Does the employer make one of the following contributions: (a) a nonelective contribution of at least 2% of each eligible employee''s compensation, or (b) a matching contribution of at least 100% of salary reductions up to 6% of compensation?', 'RADIO', 'Yes|No', 'The Simple Cafeteria Plan requires the employer to meet one of these contribution requirements. Check your plan document for the contribution formula.', 'Section F  Simple Cafeteria Plan Safe Harbor', 1, 1900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'f_eligibility_requirement', 'Are all employees with at least 1,000 hours of service in the preceding plan year eligible to participate?', 'RADIO', 'Yes|No', 'The Simple Cafeteria Plan requires that all employees meeting the 1,000-hour threshold be eligible. Standard excludable employee rules (under age 21, CBA, nonresident alien) still apply.', 'Section F  Simple Cafeteria Plan Safe Harbor', 1, 2000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_waiting_period', 'Does the plan require a minimum period of employment (waiting period) before an employee is eligible?', 'RADIO', 'Yes|No', 'If the plan requires employees to complete a waiting period before they can enroll, employees who have not yet met that requirement may be excludable from testing.', 'Section E  Plan Eligibility Conditions', 1, 2100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_waiting_period_length', 'What is the waiting period?', 'SELECT', '30 days|60 days|90 days|6 months|1 year|2 years|3 years|Other', 'For nondiscrimination testing, employees with less than the plan''s service requirement (up to 3 years) may be excluded from the testing population.', 'Section E  Plan Eligibility Conditions', 1, 2200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_minimum_age', 'Does the plan require a minimum age for eligibility?', 'RADIO', 'Yes|No', 'If the plan has a minimum age requirement, employees under that age may be excludable from testing.', 'Section E  Plan Eligibility Conditions', 1, 2300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_minimum_age_value', 'What is the minimum age?', 'NUMBER', NULL, 'Employees under this age who are not yet eligible may be excluded from testing. The maximum excludable age is 21 under §125 proposed regulations.', 'Section E  Plan Eligibility Conditions', 1, 2400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_hours_requirement', 'Does the plan require a minimum number of hours worked to be eligible?', 'RADIO', 'Yes|No', 'Part-time and seasonal employees may be excludable from testing if the plan imposes an hours or months-worked requirement.', 'Section E  Plan Eligibility Conditions', 1, 2500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_hours_requirement_value', 'What is the hours requirement?', 'SELECT', '500 hours per year|1,000 hours per year|Other', 'Under §125, employees who worked fewer than 1,000 hours in the preceding plan year may be excluded. Under §105(h), the threshold is 35 hours per week.', 'Section E  Plan Eligibility Conditions', 1, 2600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_eligibility_varies', 'Do eligibility conditions vary by employee classification?', 'RADIO', 'Yes|No', 'For example, salaried employees eligible immediately but hourly employees subject to a 90-day waiting period. If eligibility conditions differ by group, this affects how the eligibility test is evaluated.', 'Section E  Plan Eligibility Conditions', 1, 2700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'e_eligibility_varies_describe', 'Describe the classifications and their eligibility conditions', 'TEXTAREA', NULL, 'List each employee classification and the eligibility conditions that apply to it (e.g., ''Salaried  eligible immediately; Hourly  90-day waiting period; Seasonal  not eligible'').', 'Section E  Plan Eligibility Conditions', 1, 2800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'g_under_service_requirement', 'Number of employees with less than the plan''s service requirement who are not yet eligible', 'NUMBER', NULL, 'Count employees who have not yet completed the plan''s waiting period as reported in Section E. If the plan has no waiting period, enter 0. Employees can only be excluded if the plan imposes this requirement.', 'Section G  Excludable Employees (§125)', 1, 2900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'g_under_minimum_age', 'Number of employees under the plan''s minimum age requirement who are not yet eligible', 'NUMBER', NULL, 'Count employees under the minimum age reported in Section E. If the plan has no minimum age requirement, enter 0.', 'Section G  Excludable Employees (§125)', 1, 3000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'g_part_time_seasonal', 'Number of part-time or seasonal employees who worked fewer than 1,000 hours in the preceding plan year', 'NUMBER', NULL, 'Count employees who worked fewer than 1,000 hours during the preceding plan year, or who worked during fewer than 7 months of the preceding plan year.', 'Section G  Excludable Employees (§125)', 1, 3100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'g_nonresident_alien', 'Number of nonresident aliens with no US-source income from the employer', 'NUMBER', NULL, 'Count employees who are nonresident aliens and receive no earned income from US sources from this employer. If none, enter 0.', 'Section G  Excludable Employees (§125)', 1, 3200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'g_cobra', 'Number of employees participating under COBRA continuation coverage', 'NUMBER', NULL, 'Count individuals receiving benefits under COBRA continuation provisions. If none, enter 0.', 'Section G  Excludable Employees (§125)', 1, 3300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_owners_5pct', 'How many employees are more-than-5% owners of the employer (or have more-than-5% ownership attributed to them through family members)?', 'NUMBER', NULL, 'Count employees who directly or indirectly own more than 5% of voting power or value of stock (for corporations), or more than 5% of capital or profits interest (for partnerships/LLCs). Under family attribution rules, ownership by a spouse, children,', 'Section J  HCI Classification (§125)', 1, 3400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_officers_non_owners', 'How many employees hold an officer position who are NOT already counted as more-than-5% owners above?', 'NUMBER', NULL, 'Count officers (president, vice president, secretary, treasurer, or any other corporate officer) who were not already included in the ownership count above. Under §125, any officer is a Highly Compensated Individual regardless of compensation.', 'Section J  HCI Classification (§125)', 1, 3500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_high_comp_non_owner_officer', 'How many employees earned more than the indexed compensation threshold in the preceding plan year who are NOT already counted as owners or officers above?', 'NUMBER', NULL, 'For the 2026 plan year, count employees who earned more than $160,000 in 2025. For the 2025 plan year, the threshold is $155,000 based on 2024 compensation. Do not include anyone already counted as a more-than-5% owner or officer above. Include emplo', 'Section J  HCI Classification (§125)', 1, 3600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_spouse_dependent_exists', 'Are any employees the spouse or dependent of anyone identified in the questions above who are not already counted?', 'RADIO', 'Yes|No', 'This is unique to §125  spouses and dependents of HCIs are themselves HCIs regardless of their own compensation or position. Do not count anyone already included above.', 'Section J  HCI Classification (§125)', 1, 3700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_spouse_dependent_count', 'How many additional employees are spouses or dependents of HCIs?', 'NUMBER', NULL, 'Count employees who are spouses or dependents of anyone identified in the questions above, and who have not already been counted in any prior question.', 'Section J  HCI Classification (§125)', 1, 3800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_total_hci', 'Total number of HCIs (sum of all categories above)', 'NUMBER', NULL, 'This should equal the sum of all HCI counts from the questions above. Because each category excluded prior counts, this total is already deduplicated.', 'Section J  HCI Classification (§125)', 1, 3900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'j_hci_non_covered_entities', 'Of the total HCIs, how many are employees of non-covered related entities?', 'NUMBER', NULL, 'If the employer is part of a controlled group and has related entities whose employees are not eligible for the cafeteria plan, count HCIs at those entities. These individuals are HCIs who cannot participate, which affects the eligibility test ratios', 'Section J  HCI Classification (§125)', 1, 4000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'n_available_to_all', 'Is the cafeteria plan available to all non-excludable employees on the same terms and conditions?', 'RADIO', 'Yes|No', 'If every non-excludable employee has the same eligibility conditions and access to the same benefits, the plan automatically passes the §125 eligibility test. Answer No if any group of employees has different eligibility conditions, waiting periods, ', 'Section N  §125 Eligibility Test', 1, 4100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'n_classification_description', 'Describe the eligibility classification', 'TEXTAREA', NULL, 'Describe which employees are eligible and which are not, and the business criteria used (e.g., ''All salaried employees are eligible; hourly warehouse employees are not eligible''). The classification must be based on reasonable, objective business c', 'Section N  §125 Eligibility Test', 1, 4200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'n_total_non_excludable', 'Total number of non-excludable employees', 'NUMBER', NULL, 'Start with total employees across all related entities, then subtract excludable employees (those reported in Section G who meet a plan eligibility condition). This is the testing population.', 'Section N  §125 Eligibility Test', 1, 4300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'n_non_hci_eligible', 'Number of non-HCIs eligible to participate in the plan', 'NUMBER', NULL, 'Of all non-excludable non-HCI employees, how many are actually eligible to participate in the cafeteria plan?', 'Section N  §125 Eligibility Test', 1, 4400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_same_benefits_all', 'Are the same benefits offered to all participants on the same terms?', 'RADIO', 'Yes|No', 'All qualified benefits and employer contributions must be available on the same terms to all participants. The same benefits must be offered, the required employee contribution for each benefit level must be identical, and maximum benefit levels cann', 'Section O  §125 Contributions & Benefits Test', 1, 4500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_benefits_differ_describe', 'Describe how benefits or terms differ between participant groups', 'TEXTAREA', NULL, 'Explain which benefits, contribution levels, or maximum amounts differ and for which groups. For example, ''Executives receive an employer HSA contribution of $1,500; all other employees receive $750.''', 'Section O  §125 Contributions & Benefits Test', 1, 4600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_safe_harbor_health', 'Does the employer contribution for health benefits equal 100% of the cost for the majority of similarly situated HCPs, OR equal or exceed 75% of the cost of the most expensive coverage for similarly situated participants?', 'RADIO', 'Yes|No|Not applicable  no employer health contributions', 'This is a safe harbor for health benefits (not FSAs). If the employer contributes at least 75% of the most expensive health option, the contributions and benefits test is deemed satisfied for those health benefits.', 'Section O  §125 Contributions & Benefits Test', 1, 4700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_hcp_count', 'Total number of HCIs who elected one or more nontaxable benefits (HCPs)', 'NUMBER', NULL, 'Count HCIs who actually made elections under the cafeteria plan  these are Highly Compensated Participants (HCPs). Include elections for any nontaxable benefit: pre-tax premiums, Health FSA, Dependent Care FSA, HSA contributions, etc.', 'Section O  §125 Contributions & Benefits Test', 1, 4800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_non_hci_participant_count', 'Total number of non-HCIs who elected one or more nontaxable benefits', 'NUMBER', NULL, 'Count non-HCI employees who actually made elections under the cafeteria plan.', 'Section O  §125 Contributions & Benefits Test', 1, 4900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_hcp_employee_reductions', 'Total employee salary reduction amounts elected by all HCPs (employee share only)', 'NUMBER', NULL, 'Enter the total dollar amount of pre-tax salary reductions elected by all HCI participants. This is the employee-paid portion only  do not include employer contributions.', 'Section O  §125 Contributions & Benefits Test', 1, 5000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_hcp_employer_contributions', 'Total employer contribution amounts for HCPs', 'NUMBER', NULL, 'Enter the total dollar amount the employer contributes toward benefits for all HCI participants. This includes the employer share of insurance premiums and any employer contributions to FSAs, HSAs, or HRAs.', 'Section O  §125 Contributions & Benefits Test', 1, 5100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_non_hci_employee_reductions', 'Total employee salary reduction amounts elected by all non-HCI participants (employee share only)', 'NUMBER', NULL, 'Enter the total dollar amount of pre-tax salary reductions elected by all non-HCI participants. This is the employee-paid portion only.', 'Section O  §125 Contributions & Benefits Test', 1, 5200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'o_non_hci_employer_contributions', 'Total employer contribution amounts for non-HCI participants', 'NUMBER', NULL, 'Enter the total dollar amount the employer contributes toward benefits for all non-HCI participants.', 'Section O  §125 Contributions & Benefits Test', 1, 5300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'm_owners_5pct', 'How many employees are more-than-5% owners of the employer?', 'NUMBER', NULL, 'Count employees who directly or indirectly own more than 5% of the employer. This may be the same count as reported in the §125 HCI classification section. Include employees at all related entities in the controlled group.', 'Section M  Key Employee Classification (§416(i))', 1, 5400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'm_owners_1pct_150k', 'How many employees own more than 1% of the employer AND earned more than $150,000 in the preceding plan year, who are NOT already counted as more-than-5% owners above?', 'NUMBER', NULL, 'Count employees who own more than 1% but not more than 5%, and who earned more than $150,000 in the preceding plan year. The $150,000 threshold is NOT indexed for inflation. Do not include anyone already counted as a >5% owner above. Include employee', 'Section M  Key Employee Classification (§416(i))', 1, 5500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'm_officers_above_threshold', 'How many officers had annual compensation exceeding the indexed officer threshold in the preceding plan year who are NOT already counted as owners above?', 'NUMBER', NULL, 'For the 2026 plan year, count officers who earned more than $230,000 in 2025. For the 2025 plan year, the threshold is $220,000 based on 2024 compensation. Do not include anyone already counted as a >5% or >1% owner above. Include officers at all rel', 'Section M  Key Employee Classification (§416(i))', 1, 5600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'm_total_key_employees', 'Total number of Key Employees (sum of all categories above)', 'NUMBER', NULL, 'This should equal the sum of all Key Employee counts from the questions above. Note: Key Employee status is different from HCI status  an employee can be one but not the other.', 'Section M  Key Employee Classification (§416(i))', 1, 5700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'm_key_non_covered_entities', 'Of the total Key Employees, how many are employees of non-covered related entities?', 'NUMBER', NULL, 'Count Key Employees at related entities whose employees are not eligible for the cafeteria plan. If no controlled group or no non-covered entities, enter 0.', 'Section M  Key Employee Classification (§416(i))', 1, 5800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'p_key_participant_count', 'How many key employees elected one or more nontaxable benefits under the cafeteria plan?', 'NUMBER', NULL, 'Of the key employees identified in Section M, count those who actually made elections under the cafeteria plan. Key employees at non-covered related entities would not have elections.', 'Section P  §125 Key Employee Concentration Test', 1, 5900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'p_key_employee_reductions', 'Total employee salary reduction amounts elected by key employee participants (employee share only)', 'NUMBER', NULL, 'Enter the total dollar amount of pre-tax salary reductions elected by all key employee participants. This is the employee-paid portion only  do not include employer contributions.', 'Section P  §125 Key Employee Concentration Test', 1, 6000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'p_key_employer_contributions', 'Total employer contribution amounts for key employee participants', 'NUMBER', NULL, 'Enter the total dollar amount the employer contributes toward benefits for all key employee participants. This includes the employer share of insurance premiums and any employer contributions to FSAs, HSAs, or HRAs.', 'Section P  §125 Key Employee Concentration Test', 1, 6100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'h_under_3_years_service', 'Number of employees who have not completed 3 years of service prior to the beginning of the plan year', 'NUMBER', NULL, 'Count employees with fewer than 3 full years of service as of the first day of the plan year. This threshold applies regardless of the plan''s own waiting period.', 'Section H  Excludable Employees (§105(h))', 1, 6200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'h_under_age_25', 'Number of employees under age 25 at the beginning of the plan year', 'NUMBER', NULL, 'Count employees who had not reached age 25 as of the first day of the plan year. Note: this is age 25, not age 21  the §105(h) threshold is different from §125.', 'Section H  Excludable Employees (§105(h))', 1, 6300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'h_under_35_hours', 'Number of employees who customarily work fewer than 35 hours per week', 'NUMBER', NULL, 'Count employees who are customarily scheduled for fewer than 35 hours per week, or who worked fewer than 7 months in the preceding plan year. Note: this is 35 hours/week, not 1,000 hours/year  the §105(h) threshold is different from §125.', 'Section H  Excludable Employees (§105(h))', 1, 6400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'h_nonresident_alien', 'Number of nonresident aliens with no US-source income from the employer', 'NUMBER', NULL, 'Count employees who are nonresident aliens and receive no earned income from US sources from this employer. If none, enter 0. This count may be the same as reported in the §125 excludable employees section.', 'Section H  Excludable Employees (§105(h))', 1, 6500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'k_owners_10pct', 'How many employees own more than 10% of the employer (or have more-than-10% ownership attributed to them through family members)?', 'NUMBER', NULL, 'Count employees who directly or indirectly own more than 10% in value of the employer''s stock, applying §318 family attribution rules. Note: this is a higher threshold than §125 (>10% vs. >5%), so fewer individuals may qualify. Include employees at ', 'Section K  HCI Classification (§105(h))', 1, 6600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'k_top5_officers_non_owners', 'How many of the 5 highest-paid officers are NOT already counted as more-than-10% owners above?', 'NUMBER', NULL, 'Under §105(h), only the 5 highest-paid officers are HCIs  not all officers. Identify the 5 officers with the highest annual compensation and count those not already included as >10% owners. If the employer has fewer than 5 officers, count all of the', 'Section K  HCI Classification (§105(h))', 1, 6700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'k_top25pct_non_owner_officer', 'How many employees rank in the highest-paid 25% of all employees who are NOT already counted as owners or top-5 officers above?', 'NUMBER', NULL, 'Rank all employees (excluding excludable non-participants) by current plan year compensation. Count those in the top 25% who were not already included as >10% owners or top-5 officers. Include employees at all related entities in the controlled group', 'Section K  HCI Classification (§105(h))', 1, 6800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'k_total_105h_hci', 'Total number of §105(h) HCIs (sum of all categories above)', 'NUMBER', NULL, 'This should equal the sum of all §105(h) HCI counts from the questions above. Note: this number will likely differ from your §125 HCI total  the definitions are different.', 'Section K  HCI Classification (§105(h))', 1, 6900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'k_hci_non_covered_entities', 'Of the total §105(h) HCIs, how many are employees of non-covered related entities?', 'NUMBER', NULL, 'Count §105(h) HCIs at related entities whose employees are not eligible for the self-insured plan. If no controlled group or no non-covered entities, enter 0.', 'Section K  HCI Classification (§105(h))', 1, 7000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_employees_benefiting', 'How many non-excludable employees benefit under the self-insured plan?', 'NUMBER', NULL, 'For Health FSAs, ''benefit'' means the employee elected to participate (made a salary reduction election). For HRAs/MERPs, ''benefit'' means the employee is enrolled and covered. Do not count employees who are eligible but did not elect or enroll. Us', 'Section Q  §105(h) Eligibility Test', 1, 7100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_total_non_excludable', 'Total number of non-excludable employees (using §105(h) exclusions)', 'NUMBER', NULL, 'Start with total employees across all related entities, then subtract §105(h) excludable employees reported in Section H (under age 25, less than 3 years of service, fewer than 35 hours/week, CBA, nonresident alien). This number may differ from the §', 'Section Q  §105(h) Eligibility Test', 1, 7200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_eligible_to_benefit', 'How many non-excludable employees are eligible to benefit under the self-insured plan?', 'NUMBER', NULL, 'Count all non-excludable employees who are offered the opportunity to participate, whether or not they elected to. This is everyone who could enroll if they chose to.', 'Section Q  §105(h) Eligibility Test', 1, 7300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_classification_description', 'Describe the eligibility classification for the self-insured plan', 'TEXTAREA', NULL, 'Describe which employees are eligible and which are not, and the business criteria used (e.g., ''All full-time salaried employees are eligible; part-time and seasonal employees are not''). The classification must be based on reasonable, objective bus', 'Section Q  §105(h) Eligibility Test', 1, 7400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_105h_hci_benefiting', 'Number of §105(h) HCIs who benefit under the plan', 'NUMBER', NULL, 'Of the §105(h) HCIs identified in Section K, how many actually benefit under the self-insured plan? For Health FSAs, this means they elected to participate.', 'Section Q  §105(h) Eligibility Test', 1, 7500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_105h_hci_non_excludable', 'Total number of non-excludable §105(h) HCIs', 'NUMBER', NULL, 'Of all §105(h) HCIs (Section K), how many are in the non-excludable testing population?', 'Section Q  §105(h) Eligibility Test', 1, 7600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_non_hci_benefiting', 'Number of non-HCIs who benefit under the plan', 'NUMBER', NULL, 'Of all non-excludable non-HCI employees, how many actually benefit under the self-insured plan?', 'Section Q  §105(h) Eligibility Test', 1, 7700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'q_non_hci_non_excludable', 'Total number of non-excludable non-HCIs', 'NUMBER', NULL, 'Total non-excludable employees (field above) minus non-excludable §105(h) HCIs.', 'Section Q  §105(h) Eligibility Test', 1, 7800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_same_expenses', 'Are the same types of medical expenses reimbursable for all participants?', 'RADIO', 'Yes|No', 'All medical expenses covered for HCIs must also be covered for all other participants. For example, the plan cannot cover dental expenses for executives only.', 'Section R  §105(h) Benefits Test', 1, 7900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_expenses_differ_describe', 'Describe the differences in covered expenses', 'TEXTAREA', NULL, 'Explain which expenses are covered differently and for which groups.', 'Section R  §105(h) Benefits Test', 1, 8000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_same_maximum', 'Is the maximum reimbursement amount the same for all participants?', 'RADIO', 'Yes|No', 'The maximum benefit level attributable to employer contributions cannot vary based on compensation, age, or years of service. For Health FSAs, this means the same maximum election is available to everyone.', 'Section R  §105(h) Benefits Test', 1, 8100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_maximum_differ_describe', 'Describe how maximum amounts differ', 'TEXTAREA', NULL, 'Explain which groups have different maximums and what those amounts are.', 'Section R  §105(h) Benefits Test', 1, 8200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_same_cost_sharing', 'Are employee contributions or premium-sharing amounts the same for all participants?', 'RADIO', 'Yes|No|Not applicable  no employee contributions required', 'If employees must contribute to participate in the plan, the contribution amount must be the same for all participants. Differences in cost-sharing can cause a benefits test failure.', 'Section R  §105(h) Benefits Test', 1, 8300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_cost_sharing_differ_describe', 'Describe how employee contributions differ', 'TEXTAREA', NULL, 'Explain which groups pay different amounts and what those amounts are.', 'Section R  §105(h) Benefits Test', 1, 8400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_same_waiting_periods', 'Are waiting periods the same for all participants?', 'RADIO', 'Yes|No', 'If HCIs have a shorter waiting period than other employees, the plan discriminates on its face. For example, if management is eligible immediately but hourly employees wait 90 days, this is a benefits test issue.', 'Section R  §105(h) Benefits Test', 1, 8500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_waiting_differ_describe', 'Describe how waiting periods differ', 'TEXTAREA', NULL, 'Explain which groups have different waiting periods.', 'Section R  §105(h) Benefits Test', 1, 8600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_same_dependent_coverage', 'Is dependent coverage available on the same terms for all participants?', 'RADIO', 'Yes|No|Not applicable  no dependent coverage', 'All dependent coverage available to HCIs must be available on the same basis for all other participants.', 'Section R  §105(h) Benefits Test', 1, 8700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_dependent_differ_describe', 'Describe how dependent coverage differs', 'TEXTAREA', NULL, 'Explain which groups have different dependent coverage terms.', 'Section R  §105(h) Benefits Test', 1, 8800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_executive_physicals', 'Does the employer provide medical diagnostic procedures (such as executive physicals) to any group of employees that are not available to all employees?', 'RADIO', 'Yes|No', '§105(h) includes a specific exception allowing medical diagnostic procedures (routine exams, blood tests, X-rays) for a classification of employees without violating the benefits test. If yes, this may still be permissible  but it must be limited to', 'Section R  §105(h) Benefits Test', 1, 8900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_benefit_changes', 'Has any benefit been added or removed during the plan year that affected HCIs differently than other participants?', 'RADIO', 'Yes|No', 'A plan that covers a benefit while an HCI needs it and then drops coverage is discriminatory in operation. Similarly, terminating a plan or benefit in a way that disproportionately favors HCIs can cause a failure.', 'Section R  §105(h) Benefits Test', 1, 9000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'r_benefit_changes_describe', 'Describe the change and which groups were affected', 'TEXTAREA', NULL, 'Explain what benefit changed, when, and how it affected different groups of employees.', 'Section R  §105(h) Benefits Test', 1, 9100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'i_under_age_21', 'Number of employees under age 21', 'NUMBER', NULL, 'Count employees who had not reached age 21 during the plan year. These employees may be excluded only if the plan excludes them from participation.', 'Section I  Excludable Employees (§129)', 1, 9200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'i_under_1_year_service', 'Number of employees with less than 1 year of service', 'NUMBER', NULL, 'Count employees who have not completed 1 year of service. These employees may be excluded only if the plan excludes them from participation.', 'Section I  Excludable Employees (§129)', 1, 9300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'i_nonresident_alien', 'Number of nonresident aliens with no US-source income from the employer', 'NUMBER', NULL, 'Count employees who are nonresident aliens and receive no earned income from US sources from this employer. If none, enter 0.', 'Section I  Excludable Employees (§129)', 1, 9400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'i_under_25k_compensation', 'Number of employees with annual compensation less than $25,000', 'NUMBER', NULL, 'For the §129 55% Average Benefits Test only, employees earning less than $25,000 who participate through salary reduction may be excluded from the calculation. This threshold is not indexed for inflation.', 'Section I  Excludable Employees (§129)', 1, 9500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'l_owners_5pct', 'How many employees are more-than-5% owners of the employer at any time during the current or preceding plan year?', 'NUMBER', NULL, 'Count employees who directly or indirectly own more than 5% of the employer. This uses the same ownership threshold as §125 (>5%), but does NOT include spouses and dependents of owners in the HCE definition. Ownership is tested as of any time during ', 'Section L  HCE Classification (§129)', 1, 9600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'l_high_comp_non_owners', 'How many employees earned more than the indexed compensation threshold in the preceding plan year who are NOT already counted as more-than-5% owners above?', 'NUMBER', NULL, 'For the 2026 plan year, count employees who earned more than $160,000 in 2025. For the 2025 plan year, the threshold is $155,000 based on 2024 compensation. Do not include anyone already counted as a more-than-5% owner above. Include employees at all', 'Section L  HCE Classification (§129)', 1, 9700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'l_total_hce', 'Total number of §129 HCEs (sum of categories above)', 'NUMBER', NULL, 'This should equal the sum of questions above. Note: this number may differ from your §125 HCI total because §129 does not include officers as a separate category and does not include spouses/dependents of HCEs.', 'Section L  HCE Classification (§129)', 1, 9800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'l_hce_non_covered_entities', 'Of the total §129 HCEs, how many are employees of non-covered related entities?', 'NUMBER', NULL, 'Count §129 HCEs at related entities whose employees are not eligible for the Dependent Care FSA. If no controlled group or no non-covered entities, enter 0.', 'Section L  HCE Classification (§129)', 1, 9900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 's_available_to_all', 'Is the Dependent Care FSA available to all non-excludable employees on the same terms and conditions?', 'RADIO', 'Yes|No', 'If every non-excludable employee has the same eligibility conditions and access to the Dependent Care FSA, the §129 eligibility test is satisfied. Answer No if any group of employees has different eligibility conditions or access.', 'Section S  §129 Eligibility Test', 1, 10000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 's_classification_description', 'Describe the eligibility classification for the Dependent Care FSA', 'TEXTAREA', NULL, 'Describe which employees are eligible for the Dependent Care FSA and which are not, and the business criteria used. The classification must be based on reasonable, objective business criteria such as job category, salaried vs. hourly, geographic loca', 'Section S  §129 Eligibility Test', 1, 10100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 's_total_non_excludable', 'Total number of non-excludable employees (using §129 exclusions)', 'NUMBER', NULL, 'Start with total employees across all related entities, then subtract §129 excludable employees reported in Section I (under age 21, less than 1 year of service, CBA, nonresident alien). This number may differ from the §125 and §105(h) non-excludable', 'Section S  §129 Eligibility Test', 1, 10200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 's_non_hce_eligible', 'Number of non-HCEs eligible to participate in the Dependent Care FSA', 'NUMBER', NULL, 'Of all non-excludable non-HCE employees (using the §414(q) HCE definition from Section L), how many are actually eligible to participate in the Dependent Care FSA?', 'Section S  §129 Eligibility Test', 1, 10300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_same_maximum', 'Is the same maximum Dependent Care FSA benefit available to all eligible employees?', 'RADIO', 'Yes|No', 'All eligible employees must have access to the same maximum DCAP benefit. For the 2026 plan year, the statutory maximum is $7,500 (increased from $5,000 by the One Big Beautiful Bill Act of 2025). For 2025 and prior, the maximum is $5,000 ($2,500 for', 'Section T  §129 Benefits & Contributions Test', 1, 10400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_maximum_differ_describe', 'Describe how maximum amounts differ', 'TEXTAREA', NULL, 'Explain which groups have different maximums and what those amounts are.', 'Section T  §129 Benefits & Contributions Test', 1, 10500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_same_terms', 'Are the terms and conditions of the Dependent Care FSA the same for all eligible employees?', 'RADIO', 'Yes|No', 'This includes eligibility timing, enrollment procedures, reimbursement procedures, and any other plan terms. All participants must be treated the same.', 'Section T  §129 Benefits & Contributions Test', 1, 10600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_terms_differ_describe', 'Describe how terms differ', 'TEXTAREA', NULL, 'Explain which terms differ and for which groups.', 'Section T  §129 Benefits & Contributions Test', 1, 10700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_nonelective_contributions', 'Does the employer make any nonelective (employer-paid) contributions to the Dependent Care FSA?', 'RADIO', 'Yes|No', 'If the employer contributes to the DCAP on behalf of employees (beyond salary reduction), those contributions must be available on a nondiscriminatory basis.', 'Section T  §129 Benefits & Contributions Test', 1, 10800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_nonelective_same_terms', 'Are nonelective contributions available on the same terms to all eligible employees?', 'RADIO', 'Yes|No', 'Employer contributions must not favor HCEs. The same amount or formula must apply to all eligible employees.', 'Section T  §129 Benefits & Contributions Test', 1, 10900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 't_nonelective_describe', 'Describe the nonelective contribution structure', 'TEXTAREA', NULL, 'Explain the contribution formula or amount and whether it varies by any factor.', 'Section T  §129 Benefits & Contributions Test', 1, 11000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'u_owner_participant_count', 'How many more-than-5% owners have elected to participate in the Dependent Care FSA?', 'NUMBER', NULL, 'Count more-than-5% owners who made a DCAP salary reduction election for the current plan year. Include owners at all related entities in the controlled group.', 'Section U  §129 More-Than-5% Owners Test', 1, 11100, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'u_owner_election_total', 'Total DCAP election amounts for more-than-5% owner participants', 'NUMBER', NULL, 'Enter the total dollar amount of DCAP salary reductions elected by all more-than-5% owner participants for the current plan year.', 'Section U  §129 More-Than-5% Owners Test', 1, 11200, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'u_spouse_dependent_participate', 'Do any spouses or dependents of more-than-5% owners also participate in the Dependent Care FSA?', 'RADIO', 'Yes|No', 'This test includes benefits provided to spouses and dependents of more-than-5% owners in the 25% concentration calculation. This includes spouses/dependents who are employees and have their own DCAP elections.', 'Section U  §129 More-Than-5% Owners Test', 1, 11300, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'u_spouse_dependent_election_total', 'Total DCAP election amounts for spouses and dependents of more-than-5% owners', 'NUMBER', NULL, 'Enter the total dollar amount of DCAP salary reductions elected by spouses and dependents of more-than-5% owners. Do not include amounts already reported for the owners themselves.', 'Section U  §129 More-Than-5% Owners Test', 1, 11400, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'u_total_dcap_elections', 'Total DCAP election amounts for ALL participants', 'NUMBER', NULL, 'Enter the total dollar amount of DCAP salary reductions elected by all DCAP participants for the current plan year  owners, spouses/dependents, and all other employees combined.', 'Section U  §129 More-Than-5% Owners Test', 1, 11500, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'v_hce_participant_count', 'How many HCEs have elected to participate in the Dependent Care FSA?', 'NUMBER', NULL, 'Count §414(q) HCEs (from Section L) who made a DCAP salary reduction election for the current plan year.', 'Section V  §129 55% Average Benefits Test', 1, 11600, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'v_hce_election_total', 'Total DCAP election amounts for all HCE participants', 'NUMBER', NULL, 'Enter the total dollar amount of DCAP salary reductions elected by all HCE participants for the current plan year.', 'Section V  §129 55% Average Benefits Test', 1, 11700, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'v_non_hce_participant_count', 'How many non-HCEs have elected to participate in the Dependent Care FSA?', 'NUMBER', NULL, 'Count non-HCE employees who made a DCAP salary reduction election for the current plan year.', 'Section V  §129 55% Average Benefits Test', 1, 11800, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'v_non_hce_election_total', 'Total DCAP election amounts for all non-HCE participants', 'NUMBER', NULL, 'Enter the total dollar amount of DCAP salary reductions elected by all non-HCE participants for the current plan year.', 'Section V  §129 55% Average Benefits Test', 1, 11900, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'x_notes', 'Additional notes or comments', 'TEXTAREA', NULL, 'Use this space to provide any additional information, context, or explanations that may be relevant to the nondiscrimination testing.', 'Section X  Notes & Attestation', 0, 12000, 0);
INSERT INTO questionnaire_field (questionnaire_id, field_key, label, field_type, select_options, help_text, section_name, is_required, sort_order, suppressed) VALUES (@qid, 'x_attestation', 'I attest that the information provided is accurate and complete to the best of my knowledge', 'BOOLEAN', NULL, 'By checking this box, you confirm that all responses reflect the current plan design and employee data as of the beginning of the plan year.', 'Section X  Notes & Attestation', 1, 12100, 0);
